#!/usr/bin/env bash
# Brings develop up to date with main: fast-forward when possible, otherwise
# a merge commit. When develop can't be pushed (conflicts, or a ruleset that
# requires PRs), opens or updates a "Sync main → develop" PR instead.
# Needs: gh (GH_TOKEN), a clone with full history of both branches.
set -euo pipefail

BASE=${BASE:-main}
TARGET=${TARGET:-develop}
SYNC_BRANCH="sync/$BASE-to-$TARGET"
TITLE="Sync $BASE → $TARGET"
REPO=${GITHUB_REPOSITORY:-$(gh repo view --json nameWithOwner -q .nameWithOwner)}

git config user.name "github-actions[bot]"
git config user.email "41898282+github-actions[bot]@users.noreply.github.com"
git fetch --quiet origin "$BASE" "$TARGET"
base_sha=$(git rev-parse "origin/$BASE")
target_sha=$(git rev-parse "origin/$TARGET")

if git merge-base --is-ancestor "$base_sha" "$target_sha"; then
  echo "$TARGET already has everything on $BASE."
  exit 0
fi

# Opens or updates the sync PR from $SYNC_BRANCH, built on top of $1.
open_sync_pr() {
  local tip=$1 reason=$2
  if git ls-remote --exit-code --heads origin "$SYNC_BRANCH" >/dev/null; then
    # Keep whatever is already on the branch (e.g. a conflict resolution)
    # and bring the new $BASE commits on top.
    git fetch --quiet origin "$SYNC_BRANCH"
    git checkout --quiet -B "$SYNC_BRANCH" "origin/$SYNC_BRANCH"
    git merge --quiet --no-edit "$base_sha" || { git merge --abort; echo "::warning::$SYNC_BRANCH conflicts with $BASE: resolve it on the branch."; }
  else
    git checkout --quiet -B "$SYNC_BRANCH" "$tip"
  fi
  git push --quiet origin "HEAD:refs/heads/$SYNC_BRANCH"

  local body="<!-- Generated by .github/workflows/sync-develop.yml. -->
\`$TARGET\` couldn't be updated from \`$BASE\` automatically: $reason.

Resolve anything left on \`$SYNC_BRANCH\` if needed, then merge this PR with a **merge commit** so \`$TARGET\` gets every commit on \`$BASE\`."
  local existing
  # --head also matches forks' branches of the same name: skip those.
  existing=$(gh pr list --repo "$REPO" --base "$TARGET" --head "$SYNC_BRANCH" --state open \
    --json number,isCrossRepository --jq 'map(select(.isCrossRepository | not)) | .[0].number // empty')
  if [ -n "$existing" ]; then
    gh pr edit "$existing" --repo "$REPO" --title "$TITLE" --body "$body"
    echo "::warning::Updated sync PR #$existing ($reason)"
  else
    url=$(gh pr create --repo "$REPO" --base "$TARGET" --head "$SYNC_BRANCH" --title "$TITLE" --body "$body")
    echo "::warning::Opened sync PR $url ($reason)"
  fi
}

if git merge-base --is-ancestor "$target_sha" "$base_sha"; then
  # Usual case after a release merge: develop is behind main only.
  if git push --quiet origin "$base_sha:refs/heads/$TARGET"; then
    echo "::notice::Fast-forwarded $TARGET to $BASE (${base_sha:0:7})."
    exit 0
  fi
  open_sync_pr "$base_sha" "pushing to \`$TARGET\` was rejected (a ruleset may require a PR)"
  exit 0
fi

git checkout --quiet -B "$TARGET" "$target_sha"
if ! git merge --quiet --no-ff --no-edit -m "Merge $BASE into $TARGET" "$base_sha"; then
  git merge --abort
  open_sync_pr "$base_sha" "merging \`$BASE\` into \`$TARGET\` has conflicts"
  exit 0
fi
if git push --quiet origin "HEAD:refs/heads/$TARGET"; then
  echo "::notice::Merged $BASE into $TARGET ($(git rev-parse --short HEAD))."
  exit 0
fi
open_sync_pr "$(git rev-parse HEAD)" "pushing to \`$TARGET\` was rejected (a ruleset may require a PR)"
